BEGIN
  IF EXISTS (SELECT 1 FROM import_files f LEFT JOIN storage.objects o ON o.bucket_id=f.bucket AND o.name=f.path WHERE o.id IS NULL OR (o.metadata->>'size')::bigint<>f.size) THEN
